Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
ll C[777][777];
int r, c;
ll best = 1e18, best_z = -1;

void dfs(ll x, ll y, int v1, int v2) {
    ll diff = abs(x - y);
    if (best <= 1 || diff - C[v1][r] * C[v2][r] >= best) return;
    if (v1 == r - 1 && v2 == r - 1) {
        ll d = abs(x - y);
        if (d < best) { best = d; best_z = x; }
        return;
    }
    if (v1 >= r) {
        ll cur1 = C[v1][r] - C[v1 - 1][r];
        ll sum2 = C[v2][r];
        dfs(x, y + cur1 * sum2, v1 - 1, v2);
    }
    if (v2 >= r) {
        ll sum1 = C[v1][r];
        ll cur2 = C[v2][r] - C[v2 - 1][r];
        dfs(x + sum1 * cur2, y, v1, v2 - 1);
    }
}

char s[12345];
int cntA[12345], cntB[12345];
map<ll, ll> mp;

ll solve(ll x, ll y, int v1, int v2) {
    ll state = x * 10000 + v1 * 100 + v2;
    auto it = mp.find(state);
    if (it != mp.end()) return it->second;
    ll &res = mp[state];
    ll diff = abs(x - y);
    if (diff - C[v1][r] * C[v2][r] > best) return res = 0;
    if (v1 < r || v2 < r) {
        if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
            int sum = v1 + v2;
            v1 -= cntA[sum];
            v2 -= cntB[sum];
            return res = C[v1 + v2][v1];
        }
        return res = 0;
    }
    res = 0;
    char c = s[v1 + v2 - 1];
    if (c != 'B') {
        ll cur1 = C[v1][r] - C[v1 - 1][r];
        ll sum2 = C[v2][r];
        res += solve(x, y + cur1 * sum2, v1 - 1, v2);
    }
    if (c != 'A') {
        ll sum1 = C[v1][r];
        ll cur2 = C[v2][r] - C[v2 - 1][r];
        res += solve(x + sum1 * cur2, y, v1, v2 - 1);
    }
    return res;
}

int main() {
    scanf("%d %d", &r, &c);
    int N = 2 * (r + c);
    for (int i = 0; i <= N; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
    }
    // initial best via greedy
    {
        ll x = 0, y = 0;
        int v1 = r + c, v2 = r + c;
        while (v1 >= r && v2 >= r) {
            if (x > y) {
                ll cur1 = C[v1][r] - C[v1 - 1][r];
                ll sum2 = C[v2][r];
                y += cur1 * sum2;
                v1--;
            } else {
                ll sum1 = C[v1][r];
                ll cur2 = C[v2][r] - C[v2 - 1][r];
                x += sum1 * cur2;
                v2--;
            }
        }
        best = abs(x - y);
    }
    // iterative DFS using stack
    struct State { ll x, y; int v1, v2; };
    stack<State> st;
    st.push({0, 0, r + c, r + c});
    while (!st.empty()) {
        State cur = st.top(); st.pop();
        ll diff = abs(cur.x - cur.y);
        if (best <= 1 || diff - C[cur.v1][r] * C[cur.v2][r] >= best) continue;
        if (cur.v1 == r - 1 && cur.v2 == r - 1) {
            ll d = abs(cur.x - cur.y);
            if (d < best) { best = d; best_z = cur.x; }
            continue;
        }
        if (cur.v1 >= r) {
            ll cur1 = C[cur.v1][r] - C[cur.v1 - 1][r];
            ll sum2 = C[cur.v2][r];
            st.push({cur.x, cur.y + cur1 * sum2, cur.v1 - 1, cur.v2});
        }
        if (cur.v2 >= r) {
            ll sum1 = C[cur.v1][r];
            ll cur2 = C[cur.v2][r] - C[cur.v2 - 1][r];
            st.push({cur.x + sum1 * cur2, cur.y, cur.v1, cur.v2 - 1});
        }
    }
    scanf("%s", s);
    cntA[0] = cntB[0] = 0;
    for (int i = 0; i < 2 * (r + c); ++i) {
        cntA[i + 1] = cntA[i] + (s[i] == 'A');
        cntB[i + 1] = cntB[i] + (s[i] == 'B');
    }
    ll ans = solve(0, 0, r + c, r + c);
    cout << ans << endl;
    return 0;
}
